def minPath(grid, k):
    if k <= 0:
        return []
    n = len(grid)
    r, c = 0, 0
    for i in range(n):
        for j in range(n):
            if grid[i][j] == 1:
                r, c = i, j
    path = [grid[r][c]]
    for _ in range(k - 1):
        nbrs = [
            (r + dr, c + dc)
            for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1))
            if 0 <= r + dr < n and 0 <= c + dc < n
        ]
        if nbrs:
            r, c = min(nbrs, key=lambda p: grid[p[0]][p[1]])
        path.append(grid[r][c])
    return path

