def minPath(grid, k):
    n = len(grid)
    if k <= 0:
        return []

    # The values are distinct, so the smallest possible first value (1) is at a unique cell.
    start = None
    for i in range(n):
        for j in range(n):
            if grid[i][j] == 1:
                start = (i, j)
                break
        if start is not None:
            break

    r, c = start
    path = [1]
    for _ in range(k - 1):
        best = None
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < n and 0 <= nc < n:
                if best is None or grid[nr][nc] < best[0]:
                    best = (grid[nr][nc], nr, nc)
        if best is None:
            raise ValueError("no adjacent cell to move to")
        path.append(best[0])
        r, c = best[1], best[2]

    return path

