def minPath(grid, k):
    n = len(grid)
    if k <= 0 or n == 0:
        return []

    # The smallest possible first value is 1, and since values are distinct,
    # the path must start at the cell holding 1.
    i, j = next((r, c) for r in range(n) for c in range(n) if grid[r][c] == 1)

    res = []
    for step in range(k):
        res.append(grid[i][j])
        if step == k - 1:
            break
        # Greedily move to the smallest edge-adjacent neighbor.
        best = None
        for di, dj in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            ni, nj = i + di, j + dj
            if 0 <= ni < n and 0 <= nj < n:
                if best is None or grid[ni][nj] < grid[best[0]][best[1]]:
                    best = (ni, nj)
        if best is not None:
            i, j = best
    return res

