def tri(n):
    if n < 0:
        return []
    t = [0] * (n + 1)
    for k in range(n + 1):
        if k == 0:
            t[k] = 1
        elif k == 1:
            t[k] = 3
        elif k % 2 == 0:
            t[k] = 1 + k // 2
        else:
            # For odd k >= 3, t(k+1) is an even index and has a closed form.
            t_next = 1 + (k + 1) // 2
            t[k] = t[k - 1] + t[k - 2] + t_next
    return t

