def do_algebra(operators, operands):
    """
    Evaluate an expression built from `operators` and `operands` using
    standard precedence, without using eval.

    Supported operators: +, -, *, //, **
    Precedence (highest to lowest): **, then * and //, then + and -.
    ** is right-associative; all other operators are left-associative.

    Requires len(operands) == len(operators) + 1.
    """
    precedence = {
        '+': 1,
        '-': 1,
        '*': 2,
        '//': 2,
        '**': 3,
    }
    right_associative = {'**'}

    if not isinstance(operators, (list, tuple)) or not isinstance(operands, (list, tuple)):
        raise TypeError("operators and operands must be lists or tuples")
    if len(operands) != len(operators) + 1:
        raise ValueError("operands must have exactly one more element than operators")
    for op in operators:
        if op not in precedence:
            raise ValueError(f"unsupported operator: {op!r}")
    if len(operands) == 0:
        raise ValueError("at least one operand is required")

    def apply(op, left, right):
        if op == '+':
            return left + right
        if op == '-':
            return left - right
        if op == '*':
            return left * right
        if op == '//':
            return left // right
        if op == '**':
            return left ** right
        raise ValueError(f"unsupported operator: {op!r}")

    # Precedence climbing over the flat operand/operator sequence.
