import re


def compress(s):
    if not s:
        return ""
    out = []
    i = 0
    n = len(s)
    while i < n:
        ch = s[i]
        j = i
        while j < n and s[j] == ch:
            j += 1
        count = j - i
        out.append(ch)
        if count > 1:
            out.append(str(count))
        i = j
    return "".join(out)


def decompress(s):
    return "".join(
        ch * (int(num) if num else 1)
        for ch, num in re.findall(r"([A-Za-z])(\d*)", s)
    )

