def parse_kv(line):
    """Parse a config line such as 'a=1; debug; msg="hi; there"' into a dict.

    - Pairs are separated by semicolons that are not inside double quotes.
    - 'key=value' maps to the value as a string.
    - Bare keys (no '=') map to True.
    - Double-quoted values may contain semicolons and '=' characters.
      Inside quotes, a backslash escapes the next character.
    - Whitespace around keys and unquoted values is stripped.
    - Empty segments (e.g. from a trailing ';') are ignored.
    - Raises ValueError if a double quote is never closed.
    """
    parts = []
    current = []
    in_quotes = False
    escaped = False

    for ch in line:
        if escaped:
            current.append(ch)
            escaped = False
        elif in_quotes and ch == "\\":
            current.append(ch)
            escaped = True
        elif ch == '"':
            current.append(ch)
            in_quotes = not in_quotes
        elif ch == ";" and not in_quotes:
            parts.append("".join(current))
            current = []
        else:
            current.append(ch)

    if in_quotes:
        raise ValueError("unterminated quoted value in config line")

    parts.append("".join(current))

    result = {}
    for part in parts:
        part = part.strip()
        if not part:
            continue

        if "=" in part:
            key, value = part.split("=", 1)
            key = key.strip()
            value = value.strip()
            if len(value) >= 2 and value[0] == '"' and value[-1] == '"':
                value = _unescape(value[1:-1])
            result[key] = value
        else:
            result[part] = True

    return result


def _unescape(text):
    out = []
    i = 0
    while i < len(text):
        if text[i] == "\\" and i + 1 < len(text):
            out.append(text[i + 1])
            i += 2
        else:
            out.append(text[i])
            i += 1
    return "".join(out)
