from collections import OrderedDict


class TTLCache:
    """An LRU cache whose entries expire `ttl` seconds after they are written.

    The current time is always supplied by the caller as `now`. An entry
    written at time `t` is considered expired once `now >= t + ttl`.
    Reading an entry does not extend its lifetime.
    """

    def __init__(self, capacity, ttl):
        if capacity < 1:
            raise ValueError("capacity must be at least 1")
        if ttl <= 0:
            raise ValueError("ttl must be positive")
        self._capacity = capacity
        self._ttl = ttl
        # key -> (value, written_at); ordered from least to most recently used.
        self._data = OrderedDict()

    def _is_expired(self, written_at, now):
        return now >= written_at + self._ttl

    def _purge_expired(self, now):
        expired_keys = [
            key for key, (_, written_at) in self._data.items()
            if self._is_expired(written_at, now)
        ]
        for key in expired_keys:
            del self._data[key]

    def put(self, key, value, now):
        if key in self._data:
            del self._data[key]
        else:
            if len(self._data) >= self._capacity:
                # Prefer discarding expired entries over evicting live ones.
                self._purge_expired(now)
            while len(self._data) >= self._capacity:
                self._data.popitem(last=False)  # evict least recently used
        self._data[key] = (value, now)

    def get(self, key, now):
        entry = self._data.get(key)
        if entry is None:
            return None
        value, written_at = entry
        if self._is_expired(written_at, now):
            del self._data[key]
            return None
        self._data.move_to_end(key)  # mark as most recently used
        return value

    def size(self, now):
        self._purge_expired(now)
        return len(self._data)

