from collections import OrderedDict


class TTLCache:
    """LRU cache whose entries expire `ttl` seconds after they are written.

    An entry written at time `t` is live for `now` in [t, t + ttl) and is
    treated as expired once `now >= t + ttl`. Reads refresh recency but do
    not extend the lifetime of an entry.
    """

    def __init__(self, capacity, ttl):
        if capacity < 1:
            raise ValueError("capacity must be at least 1")
        if ttl <= 0:
            raise ValueError("ttl must be positive")
        self._capacity = capacity
        self._ttl = ttl
        # key -> (value, expires_at); ordered from least to most recently used.
        self._data = OrderedDict()

    def put(self, key, value, now):
        expires_at = now + self._ttl
        if key in self._data:
            self._data[key] = (value, expires_at)
            self._data.move_to_end(key)
