class VendingMachine:
    DENOMINATIONS = (25, 10, 5)

    def __init__(self, prices, coins):
        self.prices = dict(prices)
        self.coins = {d: 0 for d in self.DENOMINATIONS}
        for denomination, count in dict(coins).items():
            if denomination in self.coins:
                self.coins[denomination] = count
        self._inserted = []

    def insert(self, coin):
        if coin not in self.DENOMINATIONS:
            return False
        self._inserted.append(coin)
        return True

    def balance(self):
        return sum(self._inserted)

    def _make_change(self, amount):
        n25 = self.coins[25]
        n10 = self.coins[10]
        n5 = self.coins[5]
        best = None
