def _tokenize(text):
    tokens = []
    i = 0
    n = len(text)
    while i < n:
        c = text[i]
        if c.isspace():
            i += 1
        elif "0" <= c <= "9":
            j = i
            while j < n and "0" <= text[j] <= "9":
                j += 1
            tokens.append(("NUM", int(text[i:j])))
            i = j
        elif c in "+-*/%^()":
            tokens.append((c, c))
            i += 1
        else:
            raise SyntaxError(f"Unexpected character {c!r} at position {i}")
    return tokens


def _c_div(a, b):
    """Integer division truncating toward zero (C semantics)."""
    if b == 0:
        raise ZeroDivisionError("division by zero")
    q = abs(a) // abs(b)
    return q if (a < 0) == (b < 0) else -q


def _c_mod(a, b):
    """Remainder with sign of the dividend (C semantics)."""
    if b == 0:
        raise ZeroDivisionError("modulo by zero")
    return a - b * _c_div(a, b)


def _int_pow(base, exp):
    if exp >= 0:
        return base ** exp
    # Negative exponent: result is 1/(base**|exp|), truncated toward zero.
    if base == 0:
        raise ZeroDivisionError("zero raised to a negative power")
    if base == 1:
        return 1
    if base == -1:
        return 1 if exp % 2 == 0 else -1
    return 0


class _Parser:
    def __init__(self, tokens):
        self.tokens = tokens
        self.pos = 0

    def _peek(self):
        return self.tokens[self.pos][0] if self.pos < len(self.tokens) else None

    def _advance(self):
        tok = self.tokens[self.pos]
        self.pos += 1
        return tok

    def parse(self):
        if not self.tokens:
            raise SyntaxError("Empty expression")
        value = self._expr()
        if self.pos != len(self.tokens):
            raise SyntaxError(f"Unexpected token {self.tokens[self.pos][1]!r}")
        return value

    # expr := term (('+' | '-') term)*
    def _expr(self):
        value = self._term()
        while self._peek() in ("+", "-"):
            op = self._advance()[0]
            rhs = self._term()
            value = value + rhs if op == "+" else value - rhs
        return value

    # term := unary (('*' | '/' | '%') unary)*
    def _term(self):
        value = self._unary()
        while self._peek() in ("*", "/", "%"):
            op = self._advance()[0]
            rhs = self._unary()
            if op == "*":
                value = value * rhs
            elif op == "/":
                value = _c_div(value, rhs)
            else:
                value = _c_mod(value, rhs)
        return value

    # unary := '-' unary | power
    def _unary(self):
        if self._peek() == "-":
            self._advance()
            return -self._unary()
        return self._power()

