        if c.isspace():
            i += 1
        elif "0" <= c <= "9":
            j = i
            while j < n and "0" <= text[j] <= "9":
                j += 1
            tokens.append(("NUM", int(text[i:j])))
            i = j
        elif c in "+-*/%^()":
            tokens.append((c, c))
            i += 1
        else:
