class VendingMachine:
    VALID_COINS = (5, 10, 25)

    def __init__(self, prices, coins):
        self._prices = dict(prices)
        self._inventory = {c: int(coins.get(c, 0)) for c in self.VALID_COINS}
        self._inserted = []

    def insert(self, coin):
        if coin not in self.VALID_COINS:
            return False
        self._inserted.append(coin)
        return True

    def balance(self):
        return sum(self._inserted)

    def select(self, item):
        if item not in self._prices:
            return 'UNKNOWN'
        price = self._prices[item]
        bal = self.balance()
        if bal < price:
            return 'INSUFFICIENT'
        change = self._make_change(bal - price)
        if change is None:
            return 'NO_CHANGE'
        for c in self._inserted:
            self._inventory[c] += 1
        for c in change:
            self._inventory[c] -= 1
        self._inserted = []
        return change

    def cancel(self):
        returned = self._inserted
        self._inserted = []
        return returned

    def _make_change(self, amount):
        if amount == 0:
            return []
        items = []
        for d in sorted(self.VALID_COINS, reverse=True):
            items.extend([d] * self._inventory[d])
        n = len(items)
        INF = float('inf')
        dp = [[INF] * (amount + 1) for _ in range(n + 1)]
        dp[0][0] = 0
        for i, v in enumerate(items, 1):
            prev = dp[i - 1]
            cur = dp[i]
            for a in range(amount + 1):
                cur[a] = prev[a]
                if a >= v and prev[a - v] + 1 < cur[a]:
                    cur[a] = prev[a - v] + 1
        if dp[n][amount] == INF:
            return None
        result = []
        a = amount
        i = n
        while i > 0 and a > 0:
            if dp[i][a] == dp[i - 1][a]:
                i -= 1
            else:
                result.append(items[i - 1])
                a -= items[i - 1]
                i -= 1
        return sorted(result, reverse=True)

