        self._inserted = []
        return returned

    def select(self, item):
        if item not in self._prices:
            return 'UNKNOWN'
        price = self._prices[item]
        bal = self.balance()
        if bal < price:
            return 'INSUFFICIENT'
        # Coins the customer just inserted can also be used as change.
        pool = self._inventory + Counter(self._inserted)
        change = self._make_change(bal - price, pool)
        if change is None:
            return 'NO_CHANGE'
