        self.message = message
        self.pos = pos


def char(c):
    def parser(s, i):
        if i < len(s) and s[i] == c:
            return (c, i + 1)
        return None
    return parser


def string(t):
    def parser(s, i):
        if s.startswith(t, i):
            return (t, i + len(t))
        return None
    return parser


def satisfy(pred):
    def parser(s, i):
        if i < len(s) and pred(s[i]):
            return (s[i], i + 1)
        return None
    return parser


def seq(*parsers):
    def parser(s, i):
        values = []
        for p in parsers:
            r = p(s, i)
            if r is None:
                return None
            v, i = r
            values.append(v)
        return (values, i)
    return parser


def alt(*parsers):
    def parser(s, i):
        for p in parsers:
            r = p(s, i)
            if r is not None:
                return r
        return None
    return parser


def many(p):
    def parser(s, i):
        values = []
        while True:
            r = p(s, i)
            if r is None:
                break
            v, new_i = r
            if new_i == i:
                # Parser succeeded without consuming input; stop to avoid looping forever.
                break
            values.append(v)
            i = new_i
        return (values, i)
    return parser


def sep_by(p, sep):
    def parser(s, i):
        r = p(s, i)
        if r is None:
            return ([], i)
        v, i = r
        values = [v]
        while True:
            rs = sep(s, i)
            if rs is None:
                break
            _, j = rs
            rp = p(s, j)
            if rp is None:
                break
            v, i = rp
            values.append(v)
        return (values, i)
    return parser


def map_(p, f):
    def parser(s, i):
        r = p(s, i)
        if r is None:
            return None
        v, new_i = r
        return (f(v), new_i)
    return parser


def parse(p, s):
    r = p(s, 0)
    if r is None:
        raise ParseError("parse failed", 0)
    value, i = r
    if i != len(s):
        raise ParseError("unexpected input", i)
    return value

