def _tdiv(a, b):
    """C-style integer division: truncates toward zero."""
    if b == 0:
        raise ZeroDivisionError("division by zero")
    q = abs(a) // abs(b)
    return -q if (a < 0) != (b < 0) else q


def _tmod(a, b):
    """C-style remainder: result takes the sign of the dividend."""
    if b == 0:
        raise ZeroDivisionError("modulo by zero")
    r = abs(a) % abs(b)
    return -r if a < 0 else r


def _tpow(base, exp):
    """Integer power. Negative exponents follow truncating division,
    so 1 / base**|exp| is truncated toward zero (e.g. 2^-1 == 0)."""
    if exp >= 0:
        return base ** exp
    return _tdiv(1, base ** (-exp))


def _tokenize(s):
    tokens = []
    i = 0
    n = len(s)
    while i < n:
        c = s[i]
        if c.isspace():
            i += 1
        elif '0' <= c <= '9':
            j = i
            while j < n and '0' <= s[j] <= '9':
                j += 1
            tokens.append(('NUM', int(s[i:j])))
            i = j
        elif c in '+-*/%^()':
            tokens.append((c, None))
            i += 1
        else:
            raise SyntaxError(f"invalid character {c!r} at position {i}")
    tokens.append(('EOF', None))
    return tokens


class _Parser:
    def __init__(self, tokens):
        self.tokens = tokens
        self.pos = 0

    def peek(self):
        return self.tokens[self.pos][0]

    def advance(self):
        tok = self.tokens[self.pos]
        self.pos += 1
        return tok

    def expect(self, kind):
        if self.peek() != kind:
            raise SyntaxError(f"expected {kind!r}, got {self.peek()!r}")
        return self.advance()

    # expr := term (('+' | '-') term)*
    def parse_expr(self):
        value = self.parse_term()
        while self.peek() in ('+', '-'):
            op = self.advance()[0]
            rhs = self.parse_term()
            value = value + rhs if op == '+' else value - rhs
        return value

    # term := unary (('*' | '/' | '%') unary)*
    def parse_term(self):
        value = self.parse_unary()
        while self.peek() in ('*', '/', '%'):
            op = self.advance()[0]
            rhs = self.parse_unary()
            if op == '*':
                value = value * rhs
            elif op == '/':
                value = _tdiv(value, rhs)
            else:
                value = _tmod(value, rhs)
        return value

    # unary := '-' unary | power
    def parse_unary(self):
        if self.peek() == '-':
            self.advance()
            return -self.parse_unary()
        return self.parse_power()

    # power := primary ('^' unary)?   (right-associative; -2^2 == -(2^2))
    def parse_power(self):
        base = self.parse_primary()
        if self.peek() == '^':
            self.advance()
            exp = self.parse_unary()
            return _tpow(base, exp)
        return base

    # primary := NUMBER | '(' expr ')'
    def parse_primary(self):
        kind = self.peek()
        if kind == 'NUM':
            return self.advance()[1]
        if kind == '(':
            self.advance()
            value = self.parse_expr()
            self.expect(')')
            return value
        raise SyntaxError(f"unexpected token {kind!r}")


def evaluate(expr):
    """Evaluate an integer arithmetic expression.

    Supports + - * / % ^, unary minus, and parentheses. Division and
    modulo truncate toward zero (C semantics). Raises SyntaxError for
    malformed input and ZeroDivisionError for division by zero.
    """
    if not isinstance(expr, str):
        raise SyntaxError("expression must be a string")
    tokens = _tokenize(expr)
    if tokens[0][0] == 'EOF':
        raise SyntaxError("empty expression")
    parser = _Parser(tokens)
    value = parser.parse_expr()
    if parser.peek() != 'EOF':
        raise SyntaxError(f"unexpected token {parser.peek()!r} at end of expression")
    return value

