class ParseError(Exception):
    def __init__(self, message, pos):
        super().__init__(f"{message} at position {pos}")
        self.pos = pos


def satisfy(pred):
    def p(s, i):
        if i < len(s) and pred(s[i]):
            return (s[i], i + 1)
        return None
    return p


def char(c):
    if len(c) != 1:
        raise ValueError("char() expects a single character")
    return satisfy(lambda ch: ch == c)


def string(t):
    def p(s, i):
        if s.startswith(t, i):
            return (t, i + len(t))
        return None
    return p


def seq(*parsers):
    def p(s, i):
        values = []
        for q in parsers:
            r = q(s, i)
            if r is None:
                return None
            v, i = r
            values.append(v)
        return (values, i)
    return p


def alt(*parsers):
    def p(s, i):
        for q in parsers:
            r = q(s, i)
            if r is not None:
                return r
        return None
    return p


def many(q):
    def p(s, i):
        values = []
        while True:
            r = q(s, i)
            if r is None:
                break
            v, new_i = r
            if new_i == i:  # guard against non-consuming parsers
                break
            values.append(v)
            i = new_i
        return (values, i)
    return p


def sep_by(q, sep):
    def p(s, i):
        first = q(s, i)
        if first is None:
            return ([], i)
        v, i = first
        values = [v]
        while True:
            sr = sep(s, i)
            if sr is None:
                break
            _, j = sr
            r = q(s, j)
            if r is None:
                break  # backtrack to before the separator
            v, i = r
            values.append(v)
        return (values, i)
    return p


def map_(q, f):
    def p(s, i):
        r = q(s, i)
        if r is None:
            return None
        v, new_i = r
        return (f(v), new_i)
    return p


def parse(q, s):
    r = q(s, 0)
    if r is None:
        raise ParseError("no match", 0)
    value, i = r
    if i != len(s):
        raise ParseError("unconsumed input", i)
    return value

