from collections import Counter

VALID_COINS = (5, 10, 25)


class VendingMachine:
    def __init__(self, prices, coins=None):
        self.prices = dict(prices)
        self.coins = Counter(coins or {})
        self._inserted = []

    def insert(self, coin):
        if coin not in VALID_COINS:
            return False
        self._inserted.append(coin)
        return True

    def balance(self):
        return sum(self._inserted)

    def select(self, item):
        if item not in self.prices:
            return 'UNKNOWN'
        price = self.prices[item]
        if self.balance() < price:
            return 'INSUFFICIENT'
        change_amount = self.balance() - price
        change = self._make_change(change_amount)
        if change is None:
            return 'NO_CHANGE'
        # Deduct change from stock, then take in the customer's payment.
        for coin in change:
            self.coins[coin] -= 1
        for coin in self._inserted:
            self.coins[coin] += 1
        self._inserted = []
        return change

    def cancel(self):
        returned = list(self._inserted)
        self._inserted = []
        return returned

    def _make_change(self, amount):
        """Return the fewest coins from inventory summing to amount, or None."""
        # dp maps reachable sums -> (coin_count, coin_list)
        dp = {0: (0, [])}
        for denom, count in self.coins.items():
            if count <= 0:
                continue
            new_dp = {}
            for total, (n, combo) in dp.items():
                for k in range(count + 1):
                    t = total + k * denom
                    if t > amount:
                        break
                    cand_n = n + k
                    if t not in new_dp or cand_n < new_dp[t][0]:
                        new_dp[t] = (cand_n, combo + [denom] * k)
            dp = new_dp
        if amount not in dp:
            return None
        return sorted(dp[amount][1], reverse=True)

