from typing import Any, Callable, Optional, Tuple

Result = Optional[Tuple[Any, int]]
Parser = Callable[[str, int], Result]


class ParseError(Exception):
    def __init__(self, message: str, pos: int):
        super().__init__(f"{message} at position {pos}")
        self.message = message
        self.pos = pos


def satisfy(pred: Callable[[str], bool]) -> Parser:
    def p(s: str, i: int) -> Result:
        if i < len(s) and pred(s[i]):
            return s[i], i + 1
        return None
    return p


def char(c: str) -> Parser:
    if len(c) != 1:
        raise ValueError("char() expects a single character")
    return satisfy(lambda x: x == c)


def string(t: str) -> Parser:
    def p(s: str, i: int) -> Result:
        if s.startswith(t, i):
            return t, i + len(t)
        return None
    return p


def seq(*parsers: Parser) -> Parser:
    def p(s: str, i: int) -> Result:
        values = []
        for q in parsers:
            r = q(s, i)
            if r is None:
                return None
            v, i = r
            values.append(v)
        return values, i
    return p


def alt(*parsers: Parser) -> Parser:
    def p(s: str, i: int) -> Result:
        for q in parsers:
            r = q(s, i)
            if r is not None:
                return r
        return None
    return p


def many(parser: Parser) -> Parser:
    def p(s: str, i: int) -> Result:
        values = []
        while True:
            r = parser(s, i)
            if r is None:
                break
            v, new_i = r
            if new_i == i:
                # Zero-width match: stop to avoid an infinite loop.
                break
            values.append(v)
            i = new_i
        return values, i
    return p


def sep_by(parser: Parser, sep: Parser) -> Parser:
    def p(s: str, i: int) -> Result:
        first = parser(s, i)
        if first is None:
            return [], i
        v, i = first
        values = [v]
        while True:
            sr = sep(s, i)
            if sr is None:
                break
            _, after_sep = sr
            r = parser(s, after_sep)
            if r is None:
                break
            v, i = r
            values.append(v)
        return values, i
    return p


def map_(parser: Parser, f: Callable[[Any], Any]) -> Parser:
    def p(s: str, i: int) -> Result:
        r = parser(s, i)
        if r is None:
            return None
        v, new_i = r
        return f(v), new_i
    return p


def parse(p: Parser, s: str) -> Any:
    r = p(s, 0)
    if r is None:
        raise ParseError("parse failed", 0)
    value, i = r
    if i != len(s):
        raise ParseError("unconsumed input", i)
    return value

