    def add_vertex(v):
        if v not in adj:
            adj[v] = set()

    for v in nodes:
        add_vertex(v)

    for u, v in edges:
        if u == v:
            return None  # self-loop can never be properly colored
        add_vertex(u)
        add_vertex(v)
        adj[u].add(v)
        adj[v].add(u)

    precolored = dict(precolored) if precolored else {}
    for v, c in precolored.items():
        if not isinstance(c, int) or isinstance(c, bool) or c < 0 or c >= k:
            return None
        add_vertex(v)

    if not adj:
        return {}
    if k <= 0:
        return None

    # Precolored neighbors must not share a color.
    for v, c in precolored.items():
        for u in adj[v]:
            if u in precolored and precolored[u] == c:
                return None

    domains = {}
    for v in adj:
        if v in precolored:
            domains[v] = {precolored[v]}
        else:
            domains[v] = set(range(k))

    def search(assignment, domains):
        if len(assignment) == len(adj):
            return assignment

        # Minimum-remaining-values choice, ties broken by highest degree.
        v = min(
            (x for x in adj if x not in assignment),
            key=lambda x: (len(domains[x]), -len(adj[x])),
        )

        for c in sorted(domains[v]):
            new_assignment = dict(assignment)
            new_assignment[v] = c

            new_domains = {x: set(d) for x, d in domains.items()}
            ok = True
            for u in adj[v]:
                if u not in new_assignment:
                    new_domains[u].discard(c)
                    if not new_domains[u]:
                        ok = False
                        break
            if ok:
                result = search(new_assignment, new_domains)
                if result is not None:
                    return result
        return None

    return search({}, domains)

