    nodes receive different colors and precolored nodes keep their given colors.
    Return None if no such coloring exists.
    """
    precolored = dict(precolored) if precolored else {}

    # Collect every node, including those that appear only in edges or precolored.
    all_nodes = []
    seen = set()
    for v in list(nodes) + list(precolored.keys()):
        if v not in seen:
            seen.add(v)
            all_nodes.append(v)

    adj = {v: set() for v in all_nodes}
    for edge in edges:
        u, v = edge
        if u == v:
            return None  # a self-loop can never be properly colored
        for x in (u, v):
            if x not in adj:
                adj[x] = set()
                all_nodes.append(x)
        adj[u].add(v)
        adj[v].add(u)

    if not all_nodes:
        return {}
