    if len(c) != 1:
        raise ValueError("char() expects a single character")
    return satisfy(lambda x: x == c)


def string(t):
    def p(s, i):
        if s.startswith(t, i):
            return t, i + len(t)
        return None
    return p


def seq(*ps):
    def p(s, i):
        values = []
        for q in ps:
            r = q(s, i)
            if r is None:
                return None
            v, i = r
            values.append(v)
        return values, i
    return p


def alt(*ps):
    def p(s, i):
        for q in ps:
            r = q(s, i)
            if r is not None:
                return r
        return None
    return p


def many(q):
    def p(s, i):
        values = []
