import re


def _wrap_words(words, width):
    """Greedily pack words into lines no longer than width."""
    lines = []
    current = ""
    for word in words:
        # Hard-break words that cannot fit on any line by themselves.
        while len(word) > width:
            if current:
                lines.append(current)
                current = ""
            lines.append(word[:width])
            word = word[width:]
        if not current:
            current = word
        elif len(current) + 1 + len(word) <= width:
            current += " " + word
        else:
            lines.append(current)
            current = word
    if current:
        lines.append(current)
    return lines


def wrap_text(text, width):
    """Greedily word-wrap text to the given width.

    Paragraphs are separated by one or more blank lines in the input and are
    wrapped independently; the output keeps them separated by a single blank line.
    """
    if width < 1:
        raise ValueError("width must be at least 1")

    paragraphs = re.split(r"\n\s*\n", text)
    wrapped = []
    for paragraph in paragraphs:
        words = paragraph.split()
        if not words:
            continue
        wrapped.append("\n".join(_wrap_words(words, width)))
    return "\n\n".join(wrapped)

