            values.append(v)
        return values, i
    return q


def map_(p, f):
    def q(s, i):
        r = p(s, i)
        if r is None:
            return None
        v, new_i = r
        return f(v), new_i
    return q


def parse(p, s):
    r = p(s, 0)
    if r is None:
        raise ParseError("parse failed", 0)
    v, i = r
    if i != len(s):
