import re


def wrap_text(text, width):
    """Greedily word-wrap text to the given width.

    Paragraphs are separated by one or more blank lines and are wrapped
    independently. Each paragraph's words are packed onto lines greedily.
    A single word longer than width is placed alone on its own line
    without being broken. Paragraphs in the result are separated by one
    blank line.
    """
    if width < 1:
        raise ValueError("width must be at least 1")

    paragraphs = [p for p in re.split(r"\n\s*\n", text) if p.strip()]
    wrapped_paragraphs = []

    for paragraph in paragraphs:
        lines = []
        current = ""
        for word in paragraph.split():
            if not current:
                current = word
            elif len(current) + 1 + len(word) <= width:
                current += " " + word
            else:
                lines.append(current)
                current = word
        if current:
            lines.append(current)
        wrapped_paragraphs.append("\n".join(lines))

    return "\n\n".join(wrapped_paragraphs)

