            return (t, i + len(t))
        return None
    return _mark(p)


def seq(*parsers):
    def p(s, i):
        values = []
        for q in parsers:
            r = q(s, i)
            if r is None:
                return None
            v, i = r
            values.append(v)
        return (values, i)
    return _mark(p)


def alt(*parsers):
    def p(s, i):
        for q in parsers:
            r = q(s, i)
            if r is not None:
                return r
        return None
    return _mark(p)


def many(parser):
    def p(s, i):
        values = []
        while True:
            r = parser(s, i)
            if r is None:
                break
            v, new_i = r
            if new_i == i:
                # Zero-width match: discard it and stop to avoid looping forever.
                break
            values.append(v)
            i = new_i
        return (values, i)
    return _mark(p)


def sep_by(parser, sep):
    def p(s, i):
        items = []
        r = parser(s, i)
        if r is None:
            return ([], i)
        v, i = r
        items.append(v)
        while True:
            sr = sep(s, i)
            if sr is None:
                break
            pr = parser(s, sr[1])
            if pr is None:
                break
            v, i = pr
            items.append(v)
        return (items, i)
    return _mark(p)


def map_(f, parser):
    # Accept either (f, parser) or (parser, f). Parsers are tagged by the
    # combinators above, so the one that is not tagged is the mapping function.
    if _is_parser(f) and not _is_parser(parser):
        f, parser = parser, f

    def p(s, i):
        r = parser(s, i)
        if r is None:
            return None
        v, new_i = r
        # If the mapping function cannot take the whole sequence as one argument
        # but can take its elements as separate arguments, unpack the sequence.
        if (isinstance(v, (list, tuple))
                and not _accepts(f, 1)
                and _accepts(f, len(v))):
            return (f(*v), new_i)
        return (f(v), new_i)
    return _mark(p)


def parse(p, s):
    r = p(s, 0)
    if r is None:
        raise ParseError("parse failed", 0)
    value, i = r
    if i != len(s):
        raise ParseError("unexpected input", i)
    return value
